def test_draft_nightqc_x_summarize__mutmut_171(tmp_path, _draft_utc):
    """DRAFT — machine-verified to kill nightqc.x_summarize__mutmut_171.

    The mutant: `- _span_reason = None if span else "under the minimum judgeable span" | + _span_reason = None`
    Recorded by #3188; survived every test in the suite until this fixture.

    ⚠️ THIS ASSERTS WHAT THE CODE DOES, NOT WHAT IT SHOULD DO. Every value below is the real
    module's own recorded output under TZ=UTC, and the projection is the harness's diff of the
    real output against the mutant's — so it discriminates by construction and endorses nothing.

    Model-written provenance (unreviewed): hand-written dry-run candidate, no model involved; the asserted value is the same in all three zones
    """
    night = str(tmp_path / "2026-07-19")
    os.makedirs(night)
    just = _stamp_epoch() + 10
    for name, rows in [
        ("Polar_H10_02849638_20260719220000_ECG.txt", 100),
        ("Polar_H10_02849638_20260719220000_ACC.txt", 50),
        ("Polar_H10_02849638_20260719220000_HR.txt", 10),
        ("Wellue_O2Ring-S_S8AW_20260719220000_SPO2.csv", 900),
        ("Wellue_O2Ring-S_S8AW_20260719220000_PPG.txt", 8000),
        ("Tepna_20260719220000_LINK.csv", 5),
    ]:
        _utime(_cap(night, name, rows), just)
    s = _summarize_floating(night, _devices())

    assert s["span_reason"] == "under the minimum judgeable span"


